'use strict';
const $=(s,root=document)=>root.querySelector(s);
const I=name=>`<i class="ph ph-${name}" aria-hidden="true"></i>`;
const escapeText=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const query=new URLSearchParams(location.search);
const isSingle=query.has('screen');
const state={selected:true,category:'ALL',memo:'今天完成了一次户外跑步，用照片记录这次出发。',label:'运动',completed:false,liked:false,poked:false,theme:'light',scenario:'normal'};
let selectedView=query.get('screen')||'all';
let toastTimer;
const screens=[['today','今日','一个明确的下一步'],['capture','拍照打卡','团团陪你记录'],['success','完成庆祝','努力被温柔看见'],['team','私密小队','四个人，各自向前'],['report','每周回顾','把坚持变成故事'],['plans','我的计划','约定少一点，坚持久一点']];
const assets={wave:'assets/tuantuan-wave.svg',read:'assets/tuantuan-read.svg',camera:'assets/tuantuan-camera.svg',celebrate:'assets/tuantuan-celebrate.svg',stand:'assets/tuantuan-stand.svg',green:'assets/friend-green.svg',blue:'assets/friend-blue.svg',pink:'assets/friend-pink.svg'};
const btn=(label,action,type='green',icon='')=>`<button class="btn ${type}" data-action="${action}">${icon?I(icon):''}${label}</button>`;
const mascot=(pose,cls='',alt='原创小伙伴团团')=>`<img src="${assets[pose]}" class="${cls}" alt="${alt}">`;
function status(){return `<div class="statusbar" aria-hidden="true"><span>9:41</span><div class="status-icons"><span class="signal"><i></i><i></i><i></i><i></i></span><span class="battery"></span></div></div>`;}
function nav(active){return `<nav class="bottom-nav" aria-label="应用页面">${[['today','house','今日'],['team','users','小队'],['capture','camera','打卡'],['report','chart-bar','周报'],['plans','book-open','计划']].map(([id,ic,t])=>`<button data-go="${id}" class="${id===active?'active':''} ${id==='capture'?'capture':''}" aria-label="${t}" ${id===active?'aria-current="page"':''}>${I(ic)}<span>${t}</span></button>`).join('')}</nav>`;}
function appTop(title=''){return `<header class="app-top">${title?`<h2>${title}</h2>`:'<div class="app-logo">better together.</div>'}<div class="app-actions"><button class="icon-button" data-action="notifications" aria-label="通知">${I('bell')}<span class="dot"></span></button><button class="icon-button" data-action="settings" aria-label="设置">${I('gear')}</button></div></header>`;}
function topBack(title){return `<header class="app-top"><div class="top-back"><button data-go="today" class="icon-button" aria-label="返回今日">${I('arrow-left')}</button>${title}</div><button class="icon-button" data-action="settings" aria-label="设置">${I('gear')}</button></header>`;}
function today(){return `${appTop()}<div class="greeting"><div><h1>嗨，林一！<br>今天也<em>一起加油。</em></h1><p>你已经完成了 ${state.completed?'3':'2'} 个小约定</p></div>${mascot('wave')}</div><div class="date-row" aria-label="本周日期，星期四 19 日">${['一','二','三','四','五','六','日'].map((d,i)=>`<div class="date ${i<3?'done':i===3?'current':''}"><span>周${d}</span><b>${i<3?I('check'):16+i}</b></div>`).join('')}</div><div class="section-title"><h2>今天的小约定</h2><span>${state.completed?'3':'2'} / 3 完成</span></div><button class="task read" data-action="read-memo"><span class="task-icon">${I('book-open')}</span><span><strong>读书 20 页</strong><small>留一点时间给自己</small></span><span class="task-end">${I('check-circle')}</span></button><button class="task meal" data-action="meal-memo"><span class="task-icon">${I('fork-knife')}</span><span><strong>认真吃一餐</strong><small>今天有好好吃饭</small></span><span class="task-end">${I('check-circle')}</span></button><button class="task run live" data-go="capture"><span class="task-icon">${I('person-simple-run')}</span><span><strong>${state.completed?'户外跑步已完成':'出去跑一会儿'}</strong><small>21:00 前 · 按自己的节奏</small></span><span class="task-end">${I(state.completed?'check-circle':'arrow-right')}</span></button><div class="today-action">${btn(state.completed?'再记录一个时刻':'记录今天的小进步','go-capture','green','camera')}<p class="small-copy">不用做到完美，开始就很棒。</p></div>`;}
function capture(){return `${topBack('记录今天')}<div class="stepper" aria-label="第 1 步，共 3 步"><i class="on"></i><i></i><i></i><span>1 / 3</span></div><div class="capture-hero">${mascot('camera')}<div class="bubble">你负责行动，<br>我帮你整理！</div></div><div class="category-row" aria-label="选择分类">${['ALL','学习','运动','饮食'].map(c=>`<button class="category ${state.category===c?'selected':''}" data-category="${c}" aria-pressed="${state.category===c}">${c==='ALL'?'ALL 自动':c}</button>`).join('')}</div><div class="section-title"><h2>留下一张今天</h2><span>${state.selected?'1':'0'} / 9 张</span></div><div class="photo-slots"><button class="photo-slot ${state.selected?'selected':''}" data-action="toggle-photo" aria-label="${state.selected?'取消选择':'选择'}运动示例照片" aria-pressed="${state.selected}"><img src="assets/run.jpg" alt="运动鞋踏上户外石阶">${state.selected?`<span class="tick">${I('check')}</span>`:''}<span class="tag">当天照片 · 示例</span></button><button class="photo-slot add" data-action="add-photo">${I('plus')}再放一张</button></div><div class="source-buttons"><button data-action="camera">${I('camera')}拍一张</button><button data-action="album">${I('image')}从相册选</button></div><div class="hint-line">${I('shield-check')}<span>只和你的小队分享。识别暂不可用，<br>也可以先盖章。</span></div><button class="btn green" data-action="review" ${state.selected?'':'disabled'}>下一步，整理照片 ${I('arrow-right')}</button><p class="small-copy">演示识别 · 不会上传照片</p>`;}
function success(){return `${topBack('这一刻，已记录')}<div class="success-hero"><h1>好耶，又完成一件！</h1><p>小小的一步，也值得庆祝。</p><div class="success-mascot">${mascot('celebrate')}<i class="confetti a"></i><i class="confetti b"></i><i class="confetti c"></i><i class="confetti d"></i></div></div><div class="success-fact"><div class="seal">${I('check')}</div><div><strong>${state.label==='ALL'?'ALL 记录':'今日'+state.label} · 已盖章</strong><p>${state.scenario==='timeout'?'纪要生成中，打卡已完成':'照片和纪要已加入小队动态'}</p></div></div><div class="success-quote"><div class="mini-friends">${mascot('green')}${mascot('blue')}${mascot('pink')}</div><span>你的坚持，有人看见。</span></div>${btn('去看看队友的今天','go-team','green','users')}<button class="link-button" data-go="today">回到今日 ${I('arrow-right')}</button><p class="small-copy">原型效果预览 · 不增加虚拟积分</p>`;}
function team(){return `${appTop('我的小队')}<section class="squad-banner"><h1>慢慢来，也一起到。</h1><p>四个人，四种节奏，一起向前。</p><div class="squad-lineup">${mascot('stand')}${mascot('green')}${mascot('blue')}${mascot('pink')}</div><div class="member-statuses"><div><strong>我</strong><span>${state.completed?'已完成':'进行中'}</span></div><div><strong>小安</strong><span>已完成</span></div><div><strong>可可</strong><span>已完成</span></div><div><strong>阿川</strong><span>未开始</span></div></div></section><div class="team-summary"><span>${I('lock-simple')} 4 / 5 人 · 私密小队</span><button class="link-button" style="width:auto;margin:0" data-action="invite">邀请队友 ${I('plus')}</button></div><div class="section-title"><h2>队友的新鲜事</h2><span>今天</span></div><article class="feed"><div class="feed-author">${mascot(state.completed?'stand':'green')}<div><strong>${state.completed?'林一 · 我':'小安'}</strong><small>${state.completed?'刚刚':'07:18'} · 户外运动</small></div><span>已盖章</span></div><img class="feed-photo" src="assets/run.jpg" alt="户外运动照片"><p>${state.completed?escapeText(state.memo):'早一点出门，发现今天的风很舒服。'}</p><div class="feed-buttons"><button data-action="like" aria-pressed="${state.liked}">${I('heart')}${state.liked?'已点赞 · 3':'点赞 · 2'}</button><button data-action="comment">${I('chat-circle')}说两句</button></div></article><div class="overdue">${mascot('pink')}<div><strong>阿川的阅读还未完成</strong><small>08:00 截止 · 08:30 同步</small></div><button data-action="poke" ${state.poked?'disabled':''}>${state.poked?'已戳一下':'戳一下'}</button></div>`;}
function report(){return `${appTop('这一周，真不错')}<div class="report-range"><span>11 月 9 日至 15 日</span><span>个人周报</span></div><section class="report-banner"><h1>你是这周<br>打卡最积极的人！</h1><p>12 次记录，每一次<br>都藏着一点小进步。</p>${mascot('celebrate')}</section><div class="section-title"><h2>把小事，慢慢做好</h2><span>本周完成率</span></div><div class="report-stat"><strong>86<span>%</span></strong><p>完成 12 / 14 次<br>比上周多完成 2 次</p></div><div class="week-grid" role="img" aria-label="周一至周日完成次数 2、2、1、2、1、2、2，共 12 次">${[2,2,1,2,1,2,2].map((n,i)=>`<div class="week-day"><i></i><i class="${n===1?'empty':''}"></i><span>周${['一','二','三','四','五','六','日'][i]}</span></div>`).join('')}</div><div class="report-row">${I('person-simple-run')}<strong>运动</strong><span>3 / 3 次</span></div><div class="report-row">${I('book-open')}<strong>学习</strong><span>5 / 7 次</span></div><div class="report-row">${I('fork-knife')}<strong>饮食</strong><span>4 / 4 次</span></div><p class="report-note">下周试试把阅读提前一点？<br>为喜欢的事，留一段不慌张的时间。</p>${btn('把这周的坚持分享出去','share','green','share-network')}<p class="small-copy">每周日 20:00 生成 · 分享只含本人数据</p>`;}
const planItems=[['run','person-simple-run','出去跑一会儿','每周二、四、六','21:00',2,3],['read','book-open','读书 20 页','每天','22:00',4,7],['meal','fork-knife','认真吃一餐','每周一、三、五、日','20:00',2,4]];
function plans(){return `${appTop('我的小约定')}<div class="plan-header"><h1>不用贪多，<br>慢慢就很好。</h1>${mascot('read')}</div><p class="plan-sub">正在认真做的 3 件小事<br>一人最多同时进行 3 个计划</p>${planItems.map(([id,ic,title,freq,time,done,total])=>`<section class="plan-panel ${id}"><div class="top"><span class="plan-badge">${I(ic)}</span><div><h2>${escapeText(title)}</h2><p>${freq}</p></div><button data-edit="${id}" aria-label="编辑${escapeText(title)}">${I('dots-three')}</button></div><div class="mini-rail" aria-label="本周完成 ${done} 次，共 ${total} 次">${Array.from({length:total},(_,i)=>`<i class="${i<done?'done':''}"></i>`).join('')}</div><div class="plan-bottom"><span>${time} 前 · 仅小队可见</span><span>本周 ${done} / ${total}</span></div></section>`).join('')}<div class="more-space"><button class="btn white" data-action="limit">${I('plus')}给下一个小约定留点空间</button><p class="small-copy">先结束一个计划，再开始新的计划。</p></div>`;}
const templates={today,capture,success,team,report,plans};
function render(){document.body.classList.toggle('single',isSingle);const list=selectedView==='all'?screens:screens.filter(s=>s[0]===selectedView);$('#gallery').classList.toggle('focused',selectedView!=='all');$('#gallery').innerHTML=list.map(([id,title,desc])=>`<section class="screen-unit" data-screen="${id}" aria-label="${title}原型"><div class="screen-label">${title}<span>${desc}</span></div><div class="phone">${status()}<div class="screen-body">${templates[id]()}</div>${id==='success'?'':nav(id)}<div class="home-indicator"></div></div></section>`).join('');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===selectedView));$('#theme').innerHTML=I(state.theme==='light'?'moon':'sun');}
function go(id){if(!templates[id])return;selectedView=id;if(isSingle)history.replaceState(null,'',`?screen=${id}`);render();if(!isSingle)$('#gallery').scrollIntoView({behavior:'smooth',block:'start'});}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function modal(title,content){$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button data-action="close" aria-label="关闭">${I('x')}</button></div>${content}`;if(!$('#dialog').open)$('#dialog').showModal();}
function close(){$('#dialog').close();}
function review(){if(!state.selected)return;modal('整理好啦，看看对不对',`<p class="dialog-copy">这是示例 AI 结果，你可以改分类和文字。</p><div class="form-field"><label for="memo-category">这张照片属于</label><select id="memo-category">${['运动','学习','饮食','ALL'].map(c=>`<option ${c===state.label?'selected':''}>${c}</option>`).join('')}</select></div><div class="form-field"><label for="memo-copy">今日纪要</label><textarea id="memo-copy">${escapeText(state.memo)}</textarea></div><p class="form-note">运动时长：未记录 · 消耗：未记录<br>照片仅证明到场，没有来源不估算。</p>${btn('确认，给今天盖章','stamp','green','check')}<button class="link-button" data-action="ai-unavailable">查看 AI 暂不可用时的样子</button>`);}
function stamp(){state.memo=$('#memo-copy')?.value||state.memo;state.label=$('#memo-category')?.value||state.label;state.completed=true;close();go('success');}
function settings(){modal('按你的节奏来',`<label class="settings-item"><span>深色预览</span><input id="dark-setting" type="checkbox" ${state.theme==='dark'?'checked':''}></label><label class="settings-item"><span>接收小队通知</span><input type="checkbox" checked></label><button class="settings-item" style="width:100%" data-action="ai-settings">我的 AI ${I('arrow-right')}</button><p class="form-note">照片仅小队可见。原型中的设置不会修改真实账号。</p>${btn('完成','close','green')}`);$('#dark-setting').addEventListener('change',theme);}
function theme(){state.theme=state.theme==='light'?'dark':'light';document.documentElement.dataset.theme=state.theme;render();}
const actions={
 close,'go-capture':()=>go('capture'),'go-team':()=>go('team'),settings,
 'toggle-photo':()=>{state.selected=!state.selected;render();},
 'camera':()=>modal('拍下这一刻',`<p class="dialog-copy">原型展示拍照入口，暂不调用相机。你可以继续用运动示例图体验。</p>${btn('使用示例照片','use-example','green','camera')}`),
 'album':()=>modal('从相册选择',`<p class="dialog-copy">正式版支持最多 9 张当天照片，逐张检查拍摄日期。此原型使用示例图。</p>${btn('使用示例照片','use-example','green','image')}`),
 'add-photo':()=>modal('还可以记录更多',`<p class="dialog-copy">正式版每次最多 9 张，可同时记录运动、学习、饮食。这里先用一张示例展示完整流程。</p>${btn('继续整理这张照片','continue-review','green')}`),
 'use-example':()=>{state.selected=true;close();render();},'continue-review':()=>{state.selected=true;review();},review,stamp,
 'ai-unavailable':()=>{state.scenario='timeout';state.label='ALL';state.memo='纪要生成中。打卡完成后，当天内继续补识别。';modal('先盖章，也没关系',`<div class="notice">AI 暂时没有完成识别。可以先用 ALL 记录，照片与盖章状态会保留。</div><p class="dialog-copy">纪要先显示「生成中」，当天内继续补识别。</p>${btn('以 ALL 先盖章','stamp','green','check')}`);},
 'read-memo':()=>modal('读书 20 页 · 已盖章','<p class="dialog-copy">今天留了一段安静的时间阅读。章节与页码：未记录，可手动补充。</p>'+btn('记住这个时刻','close','green')),
 'meal-memo':()=>modal('认真吃一餐 · 已盖章','<p class="dialog-copy">绿叶蔬菜和一份主食。热量约 350–550 千卡，AI 估算示例，可按实际份量修改。</p>'+btn('记住这个时刻','close','green')),
 'like':()=>{state.liked=!state.liked;render();toast(state.liked?'小安收到了一份演示鼓励。':'已取消演示点赞。');},
 'comment':()=>modal('给队友说两句',`<form id="comment-form"><div class="form-field"><label for="comment">回应内容</label><textarea id="comment" required placeholder="我想说…"></textarea></div><label class="settings-item"><span>对照片提出质疑</span><input id="question" type="checkbox"></label><p class="form-note">提出质疑需写明理由。4 人小队需 3 位队友质疑才触发重打，每人每天最多 2 次。</p><button class="btn green" type="submit">发送演示回应</button></form>`),
 'poke':()=>{state.poked=true;render();toast('已戳一下。演示不会向真实队友发通知。');},
 'invite':()=>modal('一起加入慢慢来小队',`<p class="dialog-copy">4 / 5 人 · 固定时区 Asia/Shanghai</p><div class="form-field"><label for="invite-code">8 位演示邀请码</label><input id="invite-code" value="BT26 8K7M" readonly style="font-size:26px;letter-spacing:3px;text-align:center"></div><p class="form-note">正式版可展示邀请二维码、扫码或输入短码加入。演示码不能用于正式 App。</p>${btn('模拟扫码加入','join','green','scan')}`),
 'join':()=>modal('确认这个小队',`<h3>慢慢来小队</h3><p class="dialog-copy">4 / 5 人 · Asia/Shanghai<br>打卡截止与周报按小队固定时区计算。</p>${btn('确认加入演示小队','joined','green','check')}`),
 'joined':()=>{close();toast('已完成加入演示。真实账号保持不变。');},
 'share':()=>modal('分享这一周的坚持',`<p class="dialog-copy">个人周报只包含本人数据与称号，不带队友明细。</p>${btn('发送到演示小队','shared','green','users')}<div style="height:13px"></div>${btn('预览个人周报图','report-preview','white','image')}`),
 'shared':()=>{close();toast('已分享至演示小队，不会向真实队友发送。');},
 'report-preview':()=>{close();go('report');toast('正在显示个人周报，可在交付的高清原型图中查看。');},
 'limit':()=>modal('小约定不用太多','<p class="dialog-copy">你已有 3 个进行中计划。先结束一个已有计划，再开始新的计划。</p>'+btn('先把现在的做好','close','green')),
 'notifications':()=>modal('来自队友的小消息','<p class="dialog-copy"><strong>小安看见了你的阅读记录</strong><br>给你的「读书 20 页」点了赞。<br><br><strong>你上周的记录整理好了</strong><br>12 次记录，一份属于你的周报。</p>'+btn('去看看周报','open-report','green')),
 'open-report':()=>{close();go('report');},
 'ai-settings':()=>modal('我的 AI',`<p class="form-note">此处仅预览配置方式。请勿输入真实密钥。</p><div class="form-field"><label for="api-url">接口地址</label><input id="api-url" value="https://api.siliconflow.cn/v1"></div><div class="form-field"><label for="api-model">模型名称</label><input id="api-model" value="deepseek-ai/DeepSeek-V4.1-Flash"></div><p class="form-note">正式版密钥仅保存在后端，客户端不直连 AI 服务。</p>${btn('保存演示配置','save-ai','green')}`),
 'save-ai':()=>{close();toast('已保存配置演示，没有发送或存储密钥。');}
};
function editPlan(id){const p=planItems.find(p=>p[0]===id);modal('改一改小约定',`<form id="plan-form" data-plan="${id}"><div class="form-field"><label for="plan-name">计划名称</label><input id="plan-name" value="${escapeText(p[2])}" maxlength="24" required></div><div class="form-field"><label for="deadline">截止时间</label><input id="deadline" type="time" value="${p[4]}" required></div><p class="form-note">小队固定时区 Asia/Shanghai。</p><button class="btn green" type="submit">保存修改</button></form>`);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.view){selectedView=b.dataset.view;render();return;}if(b.dataset.go){go(b.dataset.go);return;}if(b.dataset.category){state.category=b.dataset.category;state.label=state.category==='ALL'?'运动':state.category;render();return;}if(b.dataset.edit){editPlan(b.dataset.edit);return;}if(b.dataset.action)actions[b.dataset.action]?.();});
document.addEventListener('submit',e=>{if(e.target.id==='comment-form'){e.preventDefault();if(!$('#comment').value.trim())return;const q=$('#question').checked;close();toast(q?'已记录演示质疑，1 / 3 人，盖章保持不变。':'演示回应已发送。');}if(e.target.id==='plan-form'){e.preventDefault();const p=planItems.find(p=>p[0]===e.target.dataset.plan);p[2]=$('#plan-name').value.trim()||p[2];p[4]=$('#deadline').value;close();render();toast('已更新原型中的计划。');}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))close();});
$('#theme').addEventListener('click',theme);
if(!screens.some(s=>s[0]===selectedView)&&selectedView!=='all')selectedView='all';
render();
